def pagehead(root,section,title,blurb,crumb=''):
 bread=f'<div class="breadcrumbs"><a href="{root}">Home</a><span>/</span>{"<a href="+chr(34)+root+"work/"+chr(34)+">Work</a><span>/</span>" if crumb else ""}<span>{escape(section)}</span></div>'
 return f'<section class="page-head"><div class="container">{bread}<div class="page-kicker">{section}</div><h1>{title}</h1><p>{blurb}</p></div></section>'

def section_title(no,kicker,title,detail=''):
 return f'<div class="section-head reveal"><div><span class="section-index">{no} &nbsp; / &nbsp; {kicker.upper()}</span><h2>{title}</h2></div>{f"<p>{detail}</p>" if detail else ""}</div>'

